<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_update_report( $report_id, $status, $note = '' ) { global $wpdb; $t = sd_core_table_names(); if ( ! sd_core_can_moderate( 'sd_review_reports' ) || ! in_array( $status, array( 'pending', 'under_review', 'resolved', 'dismissed' ), true ) ) { return new WP_Error( 'forbidden', __( 'You cannot update this report.', 'social-discovery-core' ), array( 'status' => 403 ) ); } $updated = $wpdb->update( $t['reports'], array( 'status' => $status, 'updated_at' => current_time( 'mysql', true ), 'assigned_to' => get_current_user_id() ), array( 'id' => absint( $report_id ) ), array( '%s', '%s', '%d' ), array( '%d' ) ); if ( false !== $updated ) { $wpdb->insert( $t['actions'], array( 'report_id' => absint( $report_id ), 'actor_id' => get_current_user_id(), 'action' => $status, 'note' => sanitize_textarea_field( $note ), 'created_at' => current_time( 'mysql', true ) ), array( '%d', '%d', '%s', '%s', '%s' ) ); sd_core_audit( 'report_' . $status, 'report', $report_id, 'success', $note, $report_id ); return true; } return new WP_Error( 'update_failed', __( 'The report could not be updated.', 'social-discovery-core' ), array( 'status' => 500 ) ); }
